<script setup lang="ts">
const props=defineProps<{summary:any}>()
const emit=defineEmits<{select:[value:string]}>()
const {t,locale}=useI18n(),staff=useStaffStore()
const warehouses=useWarehouseStore()
const lastOut=(value:string|null)=>value?new Intl.DateTimeFormat(locale.value,{timeZone:warehouses.currentWarehouse?.timezone||'UTC',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)):'—'
const mode=ref('quantity'),table=ref(false)
const number=(n:number)=>Number(n||0).toLocaleString(locale.value)
const buckets=computed(()=>[
 {key:'age_0_30',label:'0–30',color:'#BFB9FE'},
 {key:'age_31_90',label:'31–90',color:'#9B8AFB'},
 {key:'age_91_180',label:'91–180',color:'#7855FE'},
 {key:'age_over_180',label:'180+',color:'#4E1DBC'},
 {key:'unknown',label:t('inventory-analysis.unknown'),color:'#CDD1DA'}
].map(row=>({...row,quantity:props.summary.age_buckets?.[row.key]||0,skus:props.summary.age_sku_counts?.[row.key]||0})))
const maximum=computed(()=>mode.value==='quantity'?props.summary.total_stock:Math.max(0,...buckets.value.map(row=>row.skus)))
const width=(row:any)=>maximum.value?100*(mode.value==='quantity'?row.quantity:row.skus)/maximum.value:0
const share=(n:number)=>props.summary.total_stock?(100*n/props.summary.total_stock).toLocaleString(locale.value,{maximumFractionDigits:1})+'%':'—'
</script>
<template><WCard class="age-report"><div class="age-main"><header><h2>{{t('inventory-analysis.age')}} <small>{{number(summary.total_stock)}} {{t('inventory-analysis.pieces')}}</small></h2><div class="controls"><div role="radiogroup" :aria-label="t('inventory-age.measure')"><button v-for="key in ['quantity','skus']" :key="key" role="radio" :aria-checked="mode===key" @click="mode=key">{{t('inventory-age.'+key)}}</button></div><WButton variant="text" size="sm" @click="table=!table">{{t(table?'inventory-age.chart':'inventory-age.table')}}</WButton></div></header><div v-if="!table" class="bins"><button v-for="row in buckets" :key="row.key" class="bin" @click="emit('select',row.key)"><span>{{row.label}} {{row.key==='unknown'?'':t('inventory-analysis.days')}}</span><span class="track"><i :style="{width:width(row)+'%',background:row.color}"/></span><span class="value"><b>{{number(row.quantity)}}</b> {{t('inventory-analysis.pieces')}} · {{share(row.quantity)}} · {{t('inventory-age.sku-count',{count:number(row.skus)})}}</span></button></div><div v-else class="age-table"><table><thead><tr><th>{{t('inventory-analysis.age')}}</th><th>{{t('inventory-age.quantity')}}</th><th>{{t('inventory-age.share')}}</th><th>{{t('inventory-age.skus')}}</th></tr></thead><tbody><tr v-for="row in buckets" :key="row.key"><td><button class="bucket-link" @click="emit('select',row.key)">{{row.label}}</button></td><td>{{number(row.quantity)}}</td><td>{{share(row.quantity)}}</td><td>{{number(row.skus)}}</td></tr></tbody></table></div><p class="help">{{t('inventory-analysis.hint')}} {{t('inventory-age.sku-help')}}</p></div><aside><h3>{{t('inventory-age.oldest')}}</h3><div v-for="row in summary.aged_top||[]" :key="row.goods_id" class="aged-row"><NuxtLink v-if="staff.hasPermission('goods_read')" class="w-aged-name" :to="'/goods/detail/'+row.goods_id" :title="row.goods?.name">{{row.goods?.name}}</NuxtLink><span v-else class="name">{{row.goods?.name}}</span><b>{{number(row.quantity)}} {{t('inventory-analysis.pieces')}}</b><small>{{row.goods?.code}} · <span class="last-out">{{t('inventory-age.last-out',{date:lastOut(row.last_out_at)})}}</span></small><small>{{t('inventory-age.average',{days:row.weighted_age_days==null?'—':Number(row.weighted_age_days).toLocaleString(locale,{maximumFractionDigits:1})})}}</small></div><p v-if="!summary.aged_top?.length" class="help">{{t('inventory-age.no-aged')}}</p></aside></WCard></template>
<style scoped>
.age-report :deep(.w-card__body){padding:16px 24px 20px;display:flex;flex-wrap:wrap;gap:24px}.age-main{flex:999 1 520px;min-width:0;display:flex;flex-direction:column;gap:12px}header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}h2{margin:0;font-size:16px;line-height:24px;font-weight:600}h2 small{font-size:13px;line-height:20px;font-weight:400;color:var(--w-text-2);margin-left:8px}.controls{display:flex;align-items:center;gap:8px}[role=radiogroup]{display:flex;background:var(--w-line);padding:2px;border-radius:6px}[role=radio]{height:28px;padding:0 12px;border:0;border-radius:6px;background:transparent;font:inherit;font-size:13px;color:var(--w-text-2);cursor:pointer}[aria-checked=true]{background:var(--w-surface);box-shadow:0 1px 2px #10121b1a;font-weight:600;color:var(--w-text-1)}.bins{display:flex;flex-direction:column;gap:4px}.bucket-link{border:0;background:transparent;color:var(--w-link);font:inherit;padding:0;cursor:pointer}.bin{border:0;background:transparent;text-align:left;color:var(--w-text-1);font:inherit;cursor:pointer;display:grid;grid-template-columns:96px minmax(0,1fr) 210px;gap:12px;align-items:center;padding:6px 0;font-size:13px;line-height:20px}.bin:hover{background:var(--w-surface-2)}.bin:focus-visible{outline:2px solid var(--w-link);outline-offset:2px}.track{height:20px}.track i{display:block;height:100%;border-radius:0 4px 4px 0}.value{white-space:nowrap;color:var(--w-text-2)}b{font-weight:600;color:var(--w-text-1)}.help{font-size:12px;line-height:18px;color:var(--w-text-3);margin:0}aside{flex:1 1 300px;min-width:0;padding-left:24px;border-left:1px solid var(--w-line);display:flex;flex-direction:column;gap:8px}h3{font-size:14px;line-height:22px;font-weight:600;margin:0}.aged-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 12px;padding:6px 0;border-top:1px solid var(--w-line);font-size:13px;line-height:20px}.name,.w-aged-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--w-text-1);text-decoration:none}.w-aged-name:hover{color:var(--w-link)}.aged-row>b{text-align:right}.last-out{display:inline-block;white-space:nowrap}.aged-row small{font-size:12px;line-height:18px;color:var(--w-text-3)}.aged-row small:last-child{text-align:right}.age-table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;line-height:20px}th,td{padding:8px;border-bottom:1px solid var(--w-line);text-align:right}th{font-size:12px;color:var(--w-text-3);font-weight:500}th:first-child,td:first-child{text-align:left}@media(max-width:1100px){aside{flex-basis:100%;border-left:0;border-top:1px solid var(--w-line);padding:16px 0 0}}@media(max-width:600px){.bin{grid-template-columns:68px minmax(0,1fr);gap:4px 8px}.value{grid-column:2;font-size:12px}.controls{flex-wrap:wrap}}
</style>
